import type { CourseSentence } from './courseContent';

type VocabPair = [word: string, meaning: string];

const sentence = (
  id: string,
  en: string,
  fa: string,
  pronunciation: string,
  pattern: string,
  vocabulary: VocabPair[],
): CourseSentence => ({
  id,
  en,
  fa,
  pronunciation,
  pattern,
  vocabulary: vocabulary.map(([word, meaning]) => ({ word, meaning })),
});

